// Spawn a "!" bubble over Migen Jr.'s head when his fist gets caught.
void func_80192108_67DC28(u16 arg0) {
    u16 actor_index;

    actor_index = SpawnParticle_List_90C0_16(
        D_800E154C,
        sMigenJrHeadActor.posX.whole,
        sMigenJrHeadActor.posY.whole + 0x20,
        sMigenJrHeadActor.posZ.whole + 5
    );

    if (actor_index != 0) {
        gActors[actor_index].graphicFlags = ACTOR_GFLAG_SCALE;
        gActors[actor_index].scaleX = 1.5f;
        gActors[actor_index].scaleY = 1.5f;
        gActors[actor_index].unk_148 = 60.0f;
    }
}

void func_8019219C_67DCBC(u16 arg0) {
    s32 random_bits;
    u16 new_actor_index;

    if (!(gActiveFrames & 1)) {
        return;
    }

    new_actor_index = SpawnParticle_List_90C0_16(gGraphicListBlank, gActors[67].posX.whole, gActors[67].posY.whole - 5, 0);
    if (new_actor_index == 0) {
        return;
    }

    gActors[new_actor_index].graphicFlags = ACTOR_GFLAG_PALETTE | ACTOR_GFLAG_SCALE;
    gActors[new_actor_index].graphicIndex = GINDEX_GROUNDFLAME;
    gActors[new_actor_index].unk_130 = 67.0f;
    gActors[new_actor_index].unk_14C = gActors[67].actorType;
    gActors[new_actor_index].unk_134 = 0.0f;
    gActors[new_actor_index].unk_178 = (s32)D_8019DAF0_689610;
    gActors[new_actor_index].colorA = 0xF0;
    gActors[new_actor_index].unk_138 = -5.0f;
    gActors[new_actor_index].unk_13C_f32 = 1.0f;
    gActors[new_actor_index].scaleX = (D_8019DAE0_689600[(gActiveFrames & 6) / 2] * gActors[63].unk_168) / 10000.0f;
    random_bits = Rand() & 3;
    gActors[new_actor_index].scaleY = ((0.4 + random_bits / 20.0f) * gActors[63].unk_168) / 10000.0;
    gActors[new_actor_index].unk_148 = 1.0f;
    if (gActiveFrames & 2) {
        gActors[new_actor_index].flags |= ACTOR_FLAG_FLIPPED;
    }
}

