// breath attack particles
void func_801923B0_67DED0(u16 arg0) {
    s32 random_bits;
    u16 other_actor_index;
    u16 random_value;

    other_actor_index = MIGEN_JR_MOUTH_INDEX;
    gActors[78].unk_180--;
    if (gActors[78].unk_180 > 40) {
        gActors[78].unk_140_f32 += 0.1;
        sMigenJrHeadActor.unk_180 += 8;
    }
    else if (gActors[78].unk_180 < 20) {
        gActors[78].unk_140_f32 -= 0.15;
        sMigenJrHeadActor.unk_180 -= 8;
        gActors[other_actor_index].unk_180 -= 12;
    }

    if (gActors[78].unk_140_f32 < 0.0f) {
        return;
    }

    other_actor_index = SpawnParticle_List_90C0_16(D_800E14C8, sMigenJrMouthActor.posX.whole, sMigenJrMouthActor.posY.whole, sMigenJrMouthActor.posZ.whole + 1);
    if (other_actor_index != 0) {
        gActors[other_actor_index].graphicFlags = ACTOR_GFLAG_SCALE;
        gActors[other_actor_index].scaleX = gActors[78].unk_140_f32;
        gActors[other_actor_index].scaleY = gActors[78].unk_140_f32;
        if (gActiveFrames & 2) {
            gActors[other_actor_index].scaleX += 0.5;
            gActors[other_actor_index].scaleY += 0.5;
        }
        gActors[other_actor_index].colorA = sMigenJrHeadActor.unk_180;
        gActors[other_actor_index].var_154 = -16;
        gActors[other_actor_index].unk_148 = 0.0f;
        gActors[other_actor_index].unk_11C = 0.9f;
    }

    if (gActiveFrames & 1) {
        return;
    }

    other_actor_index = SpawnParticle_Image_90C0_16(GINDEX_01EE, 0, 0, 0);
    if (other_actor_index == 0) {
        return;
    }

    gActors[other_actor_index].graphicFlags = ACTOR_GFLAG_PALETTE | ACTOR_GFLAG_ROTZ | ACTOR_GFLAG_SCALE;
    gActors[other_actor_index].flags |= ACTOR_FLAG_UNK15;
    gActors[other_actor_index].scaleX = 2.0f;
    gActors[other_actor_index].scaleY = 0.0f;
    gActors[other_actor_index].colorA = sMigenJrMouthActor.unk_180;
    gActors[other_actor_index].colorB = 0x7F;
    random_value = (Rand() * 4) & 0x3C0;
    gActors[other_actor_index].var_160 = TO_FIXED(random_value);
    random_bits = Rand() & 0x70;
    gActors[other_actor_index].var_150 = -random_bits * FIXED_UNIT(0.0625) + FIXED_UNIT(3.5);
    gActors[other_actor_index].unk_130 = 80.0f;
    gActors[other_actor_index].unk_14C = sMigenJrMouthActor.actorType;
    gActors[other_actor_index].unk_134 = 0.0f;
    gActors[other_actor_index].unk_178 = (s32)D_8019DAFC_68961C;
    gActors[other_actor_index].var_154 = -8;
    gActors[other_actor_index].unk_138 = 0.0f;
    gActors[other_actor_index].unk_13C_f32 = 1.0f;
    gActors[other_actor_index].var_110 = 0.2f;
    if (gActiveFrames & 2) {
        gActors[other_actor_index].unk_11C = -0.05f;
    }
    else {
        gActors[other_actor_index].unk_11C = -0.1f;
    }
    gActors[other_actor_index].unk_140_f32 = 18.0f;
}

